typeDefinitions.declaration:
export interface HeadingProps extends HTMLAttributes<HTMLHeadingElement> {
  level?: 1 | 2 | 3 | 4;
  visualLevel?: 1 | 2 | 3 | 4;
}

example.snippet:
case "Heading": return state === "levels"
        ? ([1, 2, 3, 4] as const).map(level => <Heading key={level} level={level}>{c.project}</Heading>)
        : <Heading level={2}>{state === "truncated" ? `${c.project} · `.repeat(20) : c.project}</Heading>;

example.usage:
import { Heading, tcrnComponentCss } from "@tcrn/ui-react/approved";
import { tcrnTokenCss } from "@tcrn/ui-tokens";
import "@tcrn/ui-tokens/fonts.css";

export function Example() {
  return <>
    <style>{tcrnTokenCss + "\n" + tcrnComponentCss}</style>
    <div data-tcrn-root data-tcrn-theme="light" style={{ display: "grid", gap: "var(--tcrn-space-2)" }}>
      <Heading level={2} visualLevel={3}>Title</Heading>
    </div>
  </>;
}
